mapper.select:
SELECT ci.checklist_item_id AS checklistItemId, ci.contents AS contents, ci.category AS category, COALESCE(aci.is_checked, FALSE) AS checked FROM checklist_items ci
LEFT JOIN account_checklist_items aci ON aci.checklist_item_id = ci.checklist_item_id AND aci.account_id = #{accountId}
WHERE ci.category = 'COMMON'
OR ci.category = #{category}
ORDER BY CASE WHEN ci.category = 'COMMON' THEN 0 ELSE 1 END, ci.checklist_item_id ASC

mapper.delete:
DELETE FROM account_checklist_items
WHERE account_id = #{accountId}
  AND checklist_item_id = #{checklistItemId}
